class VenteProduitSerializer(serializers.ModelSerializer): transaction = TransactionSerializer() type_produit_display = serializers.CharField(source='get_type_produit_display', read_only=True) montant_total = serializers.SerializerMethodField()
class Meta: model = VenteProduit fields = [ 'id', 'transaction', 'type_produit', 'type_produit_display', 'quantite', 'prix_unitaire', 'montant_total' ]
@staticmethod def get_montant_total(obj): return obj.quantite * obj.prix_unitaire
def create(self, validated_data): transaction_data = validated_data.pop('transaction') transaction_data['type_transaction'] = 'RECETTE' transaction_data['montant'] = validated_data['quantite'] * validated_data['prix_unitaire'] transaction = Transaction.objects.create(**transaction_data) vente_produit = VenteProduit.objects.create( transaction=transaction, **validated_data ) return vente_produit
