class Meta: model = VenteProduit fields = [ 'type_produit', 'quantite', 'prix_unitaire', 'montant_total', 'description' ]
def create(self, validated_data): # Générer description automatique si non fournie if 'description' not in validated_data or not validated_data['description']: produit_display = dict(VenteProduit.PRODUITS)[validated_data['type_produit']] description_template = f"Vente {produit_display} x{validated_data['quantite']}" else: description_template = validated_data['description']
# Utiliser la méthode utilitaire pour éviter la duplication return BaseCreateSerializer.creer_transaction_et_objet( validated_data, VenteProduit, description_template )
class RecetteMultiserviceCreateSerializer(serializers.ModelSerializer): montant_total = serializers.DecimalField(max_digits=10, decimal_places=2, read_only=True) description = serializers.CharField(max_length=255, required=False) utiliser_tarif_defaut = serializers.BooleanField(default=True, write_only=True) # Nouveaux champs pour impression/photocopie type_papier = serializers.CharField(required=False, allow_blank=True) papier_personnalise = serializers.CharField(required=False, allow_blank=True)
class Meta: model = RecetteMultiservice fields = [ 'type_service', 'quantite', 'prix_unitaire', 'details', 'type_papier', 'papier_personnalise', 'montant_total', 'description', 'utiliser_tarif_defaut' ]
def create(self, validated_data): utiliser_tarif = validated_data.pop('utiliser_tarif_defaut', True)
# Option: renseigner automatiquement un prix par défaut si souhaité (photocopie) if utiliser_tarif and validated_data.get('type_service') == 'PHOTOCOPIE' and 'prix_unitaire' not in validated_data: try: tarif_service = TarifService.objects.filter( categorie='MULTISERVICE', nom_service__icontains='photocopie', actif=True ).first() if tarif_service: validated_data['prix_unitaire'] = tarif_service.prix_unitaire except TarifService.DoesNotExist: pass
# Générer description automatique si non fournie if 'description' not in validated_data or not validated_data['description']: service_display = dict(RecetteMultiservice.SERVICES)[validated_data['type_service']] description_template = f"{service_display} x{validated_data['quantite']}" else: description_template = validated_data['description']
# Utiliser la méthode utilitaire pour éviter la duplication return BaseCreateSerializer.creer_transaction_et_objet( {**validated_data, 'description': description_template}, RecetteMultiservice, description_template )
class ServicePersonnaliseSerializer(serializers.ModelSerializer): transaction = TransactionSerializer() tarif_service_nom = serializers.CharField(source='tarif_service.nom_service', read_only=True) tarif_service_unite = serializers.CharField(source='tarif_service.unite_mesure', read_only=True) montant_total = serializers.ReadOnlyField() montant_remise = serializers.ReadOnlyField() pourcentage_remise = serializers.ReadOnlyField() remise_appliquee_description = serializers.CharField(source='remise_appliquee.description', read_only=True)
class Meta: model = ServicePersonnalise fields = [ 'id', 'transaction', 'tarif_service', 'tarif_service_nom', 'tarif_service_unite', 'quantite', 'prix_unitaire_original', 'prix_unitaire_utilise', 'montant_total', 'montant_remise', 'pourcentage_remise', 'remise_appliquee', 'remise_appliquee_description', 'details_supplementaires' ]
def create(self, validated_data): transaction_data = validated_data.pop('transaction') transaction_data['type_transaction'] = 'RECETTE' transaction = Transaction.objects.create(**transaction_data) service_personnalise = ServicePersonnalise.objects.create( transaction=transaction, **validated_data ) return service_personnalise
class ServicePersonnaliseCreateSerializer(serializers.ModelSerializer): tarif_service_id = serializers.IntegerField(write_only=True) description = serializers.CharField(max_length=255, required=False) montant_total = serializers.DecimalField(max_digits=10, decimal_places=2, read_only=True) montant_remise = serializers.DecimalField(max_digits=10, decimal_places=2, read_only=True) pourcentage_remise = serializers.DecimalField(max_digits=5, decimal_places=2, read_only=True) prix_unitaire_final = serializers.DecimalField(max_digits=8, decimal_places=2, read_only=True)
class Meta: model = ServicePersonnalise fields = [ 'tarif_service_id', 'quantite', 'details_supplementaires', 'description', 'montant_total', 'montant_remise', 'pourcentage_remise', 'prix_unitaire_final' ]
@staticmethod def validate_tarif_service_id(value): try: tarif = TarifService.objects.get(id=value, actif=True) return tarif except TarifService.DoesNotExist: raise serializers.ValidationError("Service non trouvé ou inactif")
def create(self, validated_data): tarif_service = validated_data.pop('tarif_service_id')
# Générer description automatique si non fournie description = validated_data.pop('description', '') if not description: description = f"{tarif_service.nom_service} x{validated_data['quantite']} {tarif_service.unite_mesure}"
# Créer transaction temporaire pour calculer les remises transaction_temp = Transaction( type_transaction='RECETTE', montant=0, # Sera calculé automatiquement description=description ) transaction_temp.save()
# Créer service personnalisé (le save() calculera automatiquement les remises) service_personnalise = ServicePersonnalise.objects.create( transaction=transaction_temp, tarif_service=tarif_service, **validated_data )
return service_personnalise
class ServiceRapideSerializer(serializers.Serializer): """Serializer pour créer rapidement un service avec calcul automatique""" code_service = serializers.CharField(max_length=20) quantite = serializers.DecimalField(max_digits=8, decimal_places=2, default=1) description_personnalisee = serializers.CharField(max_length=255, required=False) prix_personnalise = serializers.DecimalField(max_digits=8, decimal_places=2, required=False)
@staticmethod def validate_code_service(value): try: tarif = TarifService.objects.get(code_service=value, actif=True) return tarif except TarifService.DoesNotExist: raise serializers.ValidationError(f"Service avec le code '{value}' non trouvé ou inactif")
def create(self, validated_data): tarif_service = validated_data['code_service'] quantite = validated_data['quantite'] prix_unitaire = validated_data.get('prix_personnalise', tarif_service.prix_unitaire)
# Description description = validated_data.get('description_personnalisee', f"{tarif_service.nom_service} x{quantite} {tarif_service.unite_mesure}")
# Montant total montant_total = quantite * prix_unitaire
# Créer transaction transaction = Transaction.objects.create( type_transaction='RECETTE', montant=montant_total, description=description )
# Créer service personnalisé service = ServicePersonnalise.objects.create( transaction=transaction, tarif_service=tarif_service, quantite=quantite, prix_unitaire_utilise=prix_unitaire, details_supplementaires=validated_data.get('description_personnalisee', '') )
return { 'id': service.id, 'transaction_id': transaction.id, 'service': tarif_service.nom_service, 'quantite': quantite, 'prix_unitaire': prix_unitaire, 'montant_total': montant_total, 'description': description }
class ServiceRapideAvecRemiseSerializer(serializers.Serializer): """Serializer pour créer rapidement un service avec calcul automatique des remises""" code_service = serializers.CharField(max_length=20) quantite = serializers.DecimalField(max_digits=8, decimal_places=2, default=1) description_personnalisee = serializers.CharField(max_length=255, required=False) forcer_prix = serializers.DecimalField(max_digits=8, decimal_places=2, required=False) ignorer_remises = serializers.BooleanField(default=False)
@staticmethod def validate_code_service(value): try: tarif = TarifService.objects.get(code_service=value, actif=True) return tarif except TarifService.DoesNotExist: raise serializers.ValidationError(f"Service avec le code '{value}' non trouvé ou inactif")
def create(self, validated_data): tarif_service = validated_data['code_service'] quantite = validated_data['quantite'] ignorer_remises = validated_data.get('ignorer_remises', False)
# Description description = validated_data.get('description_personnalisee', f"{tarif_service.nom_service} x{quantite} {tarif_service.unite_mesure}")
# Créer transaction transaction = Transaction.objects.create( type_transaction='RECETTE', montant=0, # Sera calculé automatiquement description=description )
# Créer service personnalisé service_data = { 'transaction': transaction, 'tarif_service': tarif_service, 'quantite': quantite, }
# Forcer un prix spécifique si demandé if 'forcer_prix' in validated_data: service_data['prix_unitaire_utilise'] = validated_data['forcer_prix']
service = ServicePersonnalise.objects.create(**service_data)
# Calculer les remises si pas ignorées et pas de prix forcé if not ignorer_remises and 'forcer_prix' not in validated_data: service.save() # Déclenchera le calcul automatique des remises
return { 'id': service.id, 'transaction_id': transaction.id, 'service': tarif_service.nom_service, 'quantite': float(quantite), 'prix_unitaire_original': float(service.prix_unitaire_original), 'prix_unitaire_final': float(service.prix_unitaire_utilise), 'montant_total': float(service.montant_total), 'montant_remise': float(service.montant_remise), 'pourcentage_remise': float(service.pourcentage_remise), 'remise_appliquee': service.remise_appliquee.description if service.remise_appliquee else None, 'description': description }
