class ProfilUtilisateurSerializer(serializers.ModelSerializer): username = serializers.CharField(source='user.username', read_only=True) email = serializers.CharField(source='user.email', read_only=True) first_name = serializers.CharField(source='user.first_name', read_only=True) last_name = serializers.CharField(source='user.last_name', read_only=True) role_nom = serializers.CharField(source='role.nom', read_only=True) permissions_effectives = serializers.SerializerMethodField() peut_travailler = serializers.ReadOnlyField(source='peut_travailler_maintenant')
class Meta: model = ProfilUtilisateur fields = [ 'id', 'username', 'email', 'first_name', 'last_name', 'role', 'role_nom', 'permissions_supplementaires', 'permissions_refusees', 'telephone', 'poste', 'actif', 'heure_debut_travail', 'heure_fin_travail', 'jours_travail', 'permissions_effectives', 'peut_travailler', 'date_creation', 'derniere_connexion' ]
@staticmethod def get_permissions_effectives(obj): return obj.obtenir_toutes_permissions()
class RoleCreateSerializer(serializers.ModelSerializer): permissions_ids = serializers.ListField( child=serializers.IntegerField(), write_only=True, required=False )
class Meta: model = Role fields = ['nom', 'description', 'couleur', 'permissions_ids']
def create(self, validated_data): permissions_ids = validated_data.pop('permissions_ids', []) role = Role.objects.create(**validated_data)
if permissions_ids: permissions = Permission.objects.filter(id__in=permissions_ids, actif=True) role.permissions.set(permissions)
return role
class ProfilUtilisateurCreateSerializer(serializers.ModelSerializer): username = serializers.CharField(write_only=True) password = serializers.CharField(write_only=True, min_length=8) email = serializers.EmailField(write_only=True) first_name = serializers.CharField(write_only=True, required=False) last_name = serializers.CharField(write_only=True, required=False) permissions_supplementaires_ids = serializers.ListField( child=serializers.IntegerField(), write_only=True, required=False ) permissions_refusees_ids = serializers.ListField( child=serializers.IntegerField(), write_only=True, required=False )
class Meta: model = ProfilUtilisateur fields = [ 'username', 'password', 'email', 'first_name', 'last_name', 'role', 'permissions_supplementaires_ids', 'permissions_refusees_ids', 'telephone', 'poste', 'heure_debut_travail', 'heure_fin_travail', 'jours_travail' ]
def create(self, validated_data): # Extraire les données utilisateur user_data = { 'username': validated_data.pop('username'), 'email': validated_data.pop('email'), 'first_name': validated_data.pop('first_name', ''), 'last_name': validated_data.pop('last_name', ''), } password = validated_data.pop('password')
# Extraire les permissions permissions_supp_ids = validated_data.pop('permissions_supplementaires_ids', []) permissions_ref_ids = validated_data.pop('permissions_refusees_ids', [])
# Créer l'utilisateur user = User.objects.create_user(password=password, **user_data)
# Créer/Mettre à jour le profil profil = ProfilUtilisateur.objects.get(user=user) for key, value in validated_data.items(): setattr(profil, key, value) profil.save()
# Assigner les permissions if permissions_supp_ids: permissions_supp = Permission.objects.filter(id__in=permissions_supp_ids, actif=True) profil.permissions_supplementaires.set(permissions_supp)
if permissions_ref_ids: permissions_ref = Permission.objects.filter(id__in=permissions_ref_ids, actif=True) profil.permissions_refusees.set(permissions_ref)
return profil
class PermissionCheckSerializer(serializers.Serializer): """Serializer pour vérifier les permissions d'un utilisateur""" user_id = serializers.IntegerField() permission_code = serializers.CharField(max_length=50)
@staticmethod def validate_user_id(value): try: user = User.objects.get(id=value) return user except User.DoesNotExist: raise serializers.ValidationError("Utilisateur non trouvé")
@staticmethod def validate_permission_code(value): if not Permission.objects.filter(code_permission=value, actif=True).exists(): raise serializers.ValidationError("Permission non trouvée") return value
class TypePapierSerializer(serializers.ModelSerializer): """Serializer pour les types de papier dynamiques""" class Meta: model = TypePapier fields = [ 'id', 'nom', 'code', 'prix_unitaire', 'description', 'actif', 'date_creation', 'date_modification' ] read_only_fields = ['date_creation', 'date_modification']
class BaseCreateSerializer: """Classe utilitaire pour éviter la duplication dans les serializers de création"""
@staticmethod def creer_transaction_et_objet(validated_data, model_class, description_template=None): """ Méthode utilitaire pour créer une transaction et l'objet associé """ # Générer description automatique si non fournie if 'description' not in validated_data or not validated_data['description']: if description_template: validated_data['description'] = description_template
# Calculer montant total montant_total = validated_data['quantite'] * validated_data['prix_unitaire']
# Créer transaction transaction_data = { 'type_transaction': 'RECETTE', 'montant': montant_total, 'description': validated_data.pop('description') } transaction = Transaction.objects.create(**transaction_data)
# Créer l'objet associé objet = model_class.objects.create( transaction=transaction, **validated_data ) return objet

